import type { GeospatialCamera, GeospatialLimits } from "@babylonjs/lite";

const TWO_PI = Math.PI * 2;
const EPS = 1e-9;

type NumberGetter = (this: GeospatialCamera) => number;
type NumberSetter = (this: GeospatialCamera, value: number) => void;
type LimitsSetter = (this: GeospatialCamera, value: GeospatialLimits) => void;
type OrientationSetter = (this: GeospatialCamera, yaw: number, pitch: number, radius: number, center: unknown) => void;

interface ModeState {
  limits: GeospatialLimits;
  radiusGetter?: NumberGetter;
  radiusSetter?: NumberSetter;
  radiusValue?: number;
  radiusInstalled: boolean;
  yawGetter?: NumberGetter;
  yawSetter?: NumberSetter;
  yawValue?: number;
  yawInstalled: boolean;
  limitsSetter?: LimitsSetter;
  limitsInstalled: boolean;
  orientationOriginal?: OrientationSetter;
  orientationInstalled: boolean;
  applying: boolean;
}

const modeStates = new WeakMap<GeospatialCamera, ModeState>();

function normalizeRadians(angle: number): number {
  if (!Number.isFinite(angle)) return 0;
  let a = angle % TWO_PI;
  if (a > Math.PI) a -= TWO_PI;
  else if (a < -Math.PI) a += TWO_PI;
  return a;
}

function angularDistance(a: number, b: number): number {
  const d = Math.abs(normalizeRadians(a - b));
  return d > Math.PI ? TWO_PI - d : d;
}

function clampRadius(value: number, limits: GeospatialLimits): number {
  let min = Number(limits.radiusMin);
  let max = Number(limits.radiusMax);
  if (!Number.isFinite(min)) min = Number.isFinite(max) ? max : -Infinity;
  if (!Number.isFinite(max)) max = Number.isFinite(min) ? min : Infinity;
  if (min > max) { const t = min; min = max; max = t; }
  if (!Number.isFinite(value)) return Number.isFinite(min) ? min : Number.isFinite(max) ? max : 0;
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

function clampYaw(value: number, limits: GeospatialLimits): number {
  let min = Number(limits.yawMin);
  let max = Number(limits.yawMax);
  if (!Number.isFinite(min)) min = Number.isFinite(max) ? max : -Math.PI;
  if (!Number.isFinite(max)) max = Number.isFinite(min) ? min : Math.PI;
  if (Number.isFinite(min) && Number.isFinite(max) && max - min >= TWO_PI - EPS) {
    return normalizeRadians(value);
  }
  min = normalizeRadians(min);
  max = normalizeRadians(max);
  if (Math.abs(max - min) < EPS) return min;
  if (min <= max) {
    if (value < min) return min;
    if (value > max) return max;
    return value;
  }
  if (value >= min || value <= max) return value;
  const dMin = angularDistance(value, min);
  const dMax = angularDistance(value, max);
  return dMin <= dMax ? min : max;
}
