    set: function (this: GeospatialCamera, value: number) {
      const raw = Number(value);
      const next = Number.isFinite(raw)
        ? clampRadius(raw, state.limits)
        : clampRadius(readRadius(this, state), state.limits);
      if (state.radiusSetter) state.radiusSetter.call(this, next);
      else state.radiusValue = next;
